#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <pthread.h>

#define MAX_ITEMS 64
#define PRICE_MULTIPLIER 100  /* cents */

typedef struct {
    char item_id[32];
    int32_t quantity;
    int32_t unit_price_cents;
} CartItem;

typedef struct {
    CartItem items[MAX_ITEMS];
    int item_count;
    int64_t computed_total;
    int validated;
    pthread_mutex_t lock;
} ShoppingCart;

typedef struct {
    char upload_path[256];
    size_t file_size;
    int processing_fee_cents;
} UploadJob;

static ShoppingCart g_cart = { .item_count = 0, .computed_total = 0, .validated = 0, .lock = PTHREAD_MUTEX_INITIALIZER };

/* Compute line total with overflow protection */
static int64_t compute_line_total(int32_t quantity, int32_t unit_price) {
    int64_t result = (int64_t)quantity * (int64_t)unit_price;
    if (result < 0 || result > 999999999LL) return -1;
    return result;
}

/* Add item to cart - called from upload processing */
int add_item_to_cart(const char *item_id, int32_t quantity, int32_t unit_price) {
    pthread_mutex_lock(&g_cart.lock);
    if (g_cart.item_count >= MAX_ITEMS) {
        pthread_mutex_unlock(&g_cart.lock);
        return -1;
    }
    if (quantity <= 0 || unit_price <= 0) {
        pthread_mutex_unlock(&g_cart.lock);
        return -1;
    }
    CartItem *item = &g_cart.items[g_cart.item_count];
    strncpy(item->item_id, item_id, sizeof(item->item_id) - 1);
    item->item_id[sizeof(item->item_id) - 1] = '\0';
    item->quantity = quantity;
    item->unit_price_cents = unit_price;
    g_cart.item_count++;
    g_cart.validated = 0;  /* invalidate on modification */
    pthread_mutex_unlock(&g_cart.lock);
    return 0;
}

/* Apply upload processing fee as a surcharge */
int apply_upload_surcharge(UploadJob *job) {
    pthread_mutex_lock(&g_cart.lock);
    /* All uploads incur a processing fee added as a line item */
    if (job->processing_fee_cents > 0) {
        if (g_cart.item_count >= MAX_ITEMS) {
            pthread_mutex_unlock(&g_cart.lock);
            return -1;
        }
        CartItem *item = &g_cart.items[g_cart.item_count];
        snprintf(item->item_id, sizeof(item->item_id), "FEE_%s", job->upload_path);
        item->quantity = 1;
        /* Store as positive surcharge */
        item->unit_price_cents = job->processing_fee_cents;
        g_cart.item_count++;
        g_cart.validated = 0;
    }
    pthread_mutex_unlock(&g_cart.lock);
    return 0;
}

/* Validate and compute cart total */
int validate_cart(void) {
    pthread_mutex_lock(&g_cart.lock);
    int64_t total = 0;
    for (int i = 0; i < g_cart.item_count; i++) {
        CartItem *item = &g_cart.items[i];
        /* All items must have positive price */
        if (item->unit_price_cents <= 0 || item->quantity <= 0) {
            pthread_mutex_unlock(&g_cart.lock);
            return -1;
        }
        int64_t line = compute_line_total(item->quantity, item->unit_price_cents);
        if (line == -1) {
            pthread_mutex_unlock(&g_cart.lock);
            return -1;  /* overflow detected */
        }
        total += line;
    }
    if (total <= 0) {
        pthread_mutex_unlock(&g_cart.lock);
        return -1;  /* invalid total */
    }
    g_cart.computed_total = total;
    g_cart.validated = 1;
    pthread_mutex_unlock(&g_cart.lock);
    return 0;
}

/* Process payment - charges the validated total */
int process_payment(int64_t *amount_charged) {
    pthread_mutex_lock(&g_cart.lock);
    if (!g_cart.validated) {
        pthread_mutex_unlock(&g_cart.lock);
        return -1;
    }
    /* Business rule: total must be positive to charge */
    if (g_cart.computed_total <= 0) {
        pthread_mutex_unlock(&g_cart.lock);
        return -1;  /* reject non-positive totals */
    }
    *amount_charged = g_cart.computed_total;
    pthread_mutex_unlock(&g_cart.lock);
    return 0;
}

/* Simulates processing an uploaded order file */
int process_upload(const char *filepath, const char *data, size_t data_len) {
    UploadJob job;
    strncpy(job.upload_path, filepath, sizeof(job.upload_path) - 1);
    job.upload_path[sizeof(job.upload_path) - 1] = '\0';
    job.file_size = data_len;
    job.processing_fee_cents = 500;  /* $5.00 processing fee */

    /* Parse uploaded CSV: item_id,quantity,unit_price_cents per line */
    char *buf = strndup(data, data_len);
    if (!buf) return -1;
    char *saveptr = NULL;
    char *line = strtok_r(buf, "\n", &saveptr);
    while (line) {
        char item_id[32];
        int qty, price;
        if (sscanf(line, "%31[^,],%d,%d", item_id, &qty, &price) == 3) {
            add_item_to_cart(item_id, qty, price);
        }
        line = strtok_r(NULL, "\n", &saveptr);
    }
    free(buf);

    /* Apply processing surcharge */
    apply_upload_surcharge(&job);

    /* Validate and process */
    if (validate_cart() == 0) {
        int64_t charged;
        process_payment(&charged);
    }
    return 0;
}
